INSERT INTO public.knowledge_articles (id, slug, title_sv, title_original, summary_sv, learn_sv, try_next_sv, category, age_label, age_5_7, age_8_9, age_10, game_format_label, format_3v3, format_5v5, format_7v7, level, content_type, language, source_name, source_type, reading_minutes, coach_value, evidence_level, original_url, checked_date, is_published, featured, sort_order, copyright_note) VALUES
('KB001', 'guide-for-nya-tranare', 'Guide för dig som är ny tränare', 'Guide: Till dig som ny tränare', 'SvFF:s praktiska startguide om ledarorganisation, material, planering och hur många ledare som behövs runt ett barnlag.', 'Hur du skapar en fungerande tränargrupp och undviker vanliga startproblem.', 'Fördela roller före träningen: en leder, en förbereder nästa yta och en fångar upp barn som behöver hjälp.', 'Börja som tränare', '5–10 år', true, true, true, '3 mot 3; 5 mot 5; 7 mot 7', true, true, true, 'Grund', 'Guide', 'Svenska', 'Svenska Fotbollförbundet', 'Nationellt förbund', 8, 'Direkt användbar', 'Officiellt utbildningsmaterial', 'https://aktiva.svenskfotboll.se/tranare/bli-tranare/guide-ny-tranare/', '2026-08-30', true, true, 1, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB002', 'svensk-spelarutbildningsplan', 'Svensk fotbolls spelarutbildningsplan', 'Svensk fotbolls spelarutbildningsplan', 'Den centrala svenska referensen för hur träning och matchmiljö ska anpassas så att spelare från sex år utvecklas och har roligt.', 'Vilka mål och principer som gäller i olika åldrar och spelformer.', 'Välj ett enda mål ur planen för nästa pass och låt alla övningar stödja samma mål.', 'Börja som tränare', '6–10 år', true, true, true, '3 mot 3; 5 mot 5; 7 mot 7', true, true, true, 'Grund', 'Guide och utbildningsplan', 'Svenska', 'Svenska Fotbollförbundet', 'Nationellt förbund', 12, 'Referensmaterial', 'Officiella riktlinjer', 'https://aktiva.svenskfotboll.se/tranare/spelarutbildning/spelarutbildningsplan/', '2026-08-30', true, true, 2, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB003', 'fotbollens-spela-lek-och-lar', 'Fotbollens spela, lek och lär', 'Fotbollens spela, lek och lär', 'Svensk barnfotbolls gemensamma värdegrund: fotboll för alla, barnens villkor, glädje, ansträngning, lärande, hållbarhet och fair play.', 'Hur barnperspektivet ska styra beslut om träning, match och bemötande.', 'Avsluta passet med frågan: Vad var roligast och vad vill ni prova igen?', 'Börja som tränare', '5–10 år', true, true, true, 'Alla', true, true, true, 'Grund', 'Riktlinje', 'Svenska', 'Svenska Fotbollförbundet', 'Nationellt förbund', 8, 'Referensmaterial', 'Officiella riktlinjer', 'https://aktiva.svenskfotboll.se/forening/tryggfotboll/fotbollens-spela-lek-och-lar/', '2026-08-30', true, true, 3, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB004', 'rolig-trygg-effektiv-traning', 'Skapa en rolig, trygg och effektiv träning', 'General Principles: Creating a fun, safe and effective practice environment', 'FIFA:s enkla grundprinciper för att organisera träning där barn är trygga, aktiva och engagerade.', 'Hur miljö, organisation och tränarbeteende tillsammans påverkar lärandet.', 'Planera ytor och lag i förväg så att första spelet kan börja inom två minuter.', 'Börja som tränare', '6–10 år', true, true, true, 'Alla smålagsspel', true, true, true, 'Grund', 'Artikel + film + övningar', 'Engelska', 'FIFA Training Centre', 'Internationellt förbund', 8, 'Direkt användbar', 'Officiellt utbildningsmaterial', 'https://www.fifatrainingcentre.com/en/practice/grassroots/grassroots-and-youth-football-essentials/grassroots-coaching-essentials/jene-general-principles-1.php', '2026-08-30', true, true, 4, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB005', 'play-practice-play', 'Planera med Play–Practice–Play', 'Ages 4-8: An introduction to Play-Practice-Play', 'En barncentrerad modell där passet börjar med spel, går över till ett tydligt träningsmoment och avslutas med spel igen.', 'Hur du skapar en enkel röd tråd utan långa genomgångar.', 'Prova 15 minuter spel, 20 minuter tematräning och 20 minuter spel med samma tema.', 'Träningsplanering', '5–8 år', true, true, false, '3 mot 3; 5 mot 5', true, true, false, 'Grund', 'Artikel + film + övningar', 'Engelska', 'FIFA Training Centre', 'Internationellt förbund', 8, 'Direkt användbar', 'Officiellt utbildningsmaterial', 'https://www.fifatrainingcentre.com/en/practice/grassroots/grassroots-and-youth-football-essentials/grassroots-coaching-essentials/an-introduction-to-play-practice-play.php', '2026-08-30', true, true, 5, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB006', 'en-traning-i-veckan', 'Få ut mer av en träning i veckan', 'Ages 8-12: Sessions for once-a-week training', 'FIFA:s ramverk för breddlag med begränsad träningstid: rolig start, många minispel och avslutande matchtillämpning.', 'Hur varje minut kan användas när laget bara tränar en gång i veckan.', 'Ta bort en köövning och ersätt den med två parallella minispel.', 'Träningsplanering', '8–10 år', false, true, true, '5 mot 5; 7 mot 7', false, true, true, 'Grund', 'Artikel + film + övningar', 'Engelska', 'FIFA Training Centre', 'Internationellt förbund', 9, 'Planeringsstöd', 'Officiellt utbildningsmaterial', 'https://www.fifatrainingcentre.com/en/practice/grassroots/grassroots-and-youth-football-essentials/grassroots-coaching-essentials/sessions-for-once-a-week-training.php', '2026-08-30', true, false, 6, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB007', 'global-analytical-global', 'Planera med Global–Analytical–Global', 'Ages 8-12: Coaching with the Global-Analytical-Global model', 'En modell som börjar i spel, isolerar en teknisk detalj och återgår till spel så att barnen får pröva färdigheten i rätt sammanhang.', 'När en kort teknikdel kan hjälpa utan att spelet försvinner.', 'Filma inte och föreläs inte: visa momentet på 30 sekunder och låt spelarna snabbt prova igen i spel.', 'Träningsplanering', '8–10 år', false, true, true, '5 mot 5; 7 mot 7', false, true, true, 'Fortsättning', 'Artikel + film + övningar', 'Engelska', 'FIFA Training Centre', 'Internationellt förbund', 9, 'Planeringsstöd', 'Officiellt utbildningsmaterial', 'https://www.fifatrainingcentre.com/en/practice/grassroots/grassroots-and-youth-football-essentials/grassroots-coaching-essentials/coaching-with-the-global-analytical-global-model.php', '2026-08-30', true, false, 7, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB008', 'strukturera-traningspass', 'Så strukturerar du ett träningspass', 'How to structure a training session', 'England Football beskriver realistiska, relevanta och repetitiva pass samt hur olika passmodeller kan väljas efter spelarnas behov.', 'Hur du kopplar syfte, övning och avslutande spel till samma tema.', 'Skriv en mening före passet: Efter träningen ska spelarna ha fått många chanser att…', 'Träningsplanering', '5–10 år', true, true, true, 'Alla smålagsspel', true, true, true, 'Grund', 'Artikel + film', 'Engelska', 'England Football Learning', 'Nationellt förbund', 5, 'Direkt användbar', 'Officiellt utbildningsmaterial', 'https://learn.englandfootball.com/articles-and-resources/coaching/resources/2023/How-to-structure-a-training-session', '2026-08-30', true, false, 8, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB009', 'tidseffektiva-traningar', 'Skapa tidseffektiva träningar', 'Spelet – Hur du skapar tidseffektiva träningar', 'SvFF:s mikroutbildning om hur planering och organisation ger mer aktivitet och mindre väntan.', 'Hur du minskar omställningstid och håller fler barn i rörelse.', 'Bygg nästa övningsyta före samlingen och återanvänd samma koner i hela passet.', 'Träningsplanering', '5–10 år', true, true, true, 'Alla', true, true, true, 'Grund', 'Mikroutbildning', 'Svenska', 'Svenska Fotbollförbundet', 'Nationellt förbund', 12, 'Planeringsstöd', 'Officiellt utbildningsmaterial', 'https://aktiva.svenskfotboll.se/tranare/mikroutbildningar/tidseffektivatraningar/', '2026-08-30', true, false, 9, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB010', 'roliga-uppvarmningar-4-8', 'Roliga och effektiva uppvärmningar', 'Ages 4-8: Creating fun and effective warm-ups', 'Tre åldersanpassade exempel där uppvärmningen samtidigt utvecklar bollfärdighet, rörelse och glädje.', 'Varför kölöpning kan ersättas med lek och bollaktivitet.', 'Ge varje barn en boll direkt och starta med en jagalek där bollen ingår.', 'Träningsplanering', '5–8 år', true, true, false, '3 mot 3; 5 mot 5', true, true, false, 'Grund', 'Artikel + film + övningar', 'Engelska', 'FIFA Training Centre', 'Internationellt förbund', 8, 'Direkt användbar', 'Officiellt utbildningsmaterial', 'https://www.fifatrainingcentre.com/en/practice/grassroots/grassroots-and-youth-football-essentials/grassroots-coaching-essentials/creating-fun-and-effective-warm-ups.php', '2026-08-30', true, false, 10, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB011', 'bollkontroll-4-8', 'Bollkontroll för yngre barn', 'Ages 4-8: Coaching children to master ball control', 'En progressiv väg från enkla bollkontakter till passning, mottagning och beslut tillsammans med medspelare.', 'Hur repetition kan ge trygghet utan att träningen blir stillastående.', 'Skapa en boll per barn och låt dem lösa tre kontrolluppgifter i egen takt.', 'Teknik med boll', '5–8 år', true, true, false, '3 mot 3; 5 mot 5', true, true, false, 'Grund', 'Artikel + film + övningar', 'Engelska', 'FIFA Training Centre', 'Internationellt förbund', 9, 'Direkt användbar', 'Officiellt utbildningsmaterial', 'https://www.fifatrainingcentre.com/en/practice/grassroots/grassroots-and-youth-football-essentials/grassroots-coaching-essentials/coaching-children-to-master-ball-control.php', '2026-08-30', true, true, 11, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB012', 'dribbling-positiv-start', 'Dribbling som en positiv start', 'Ages 4-8: Dribbling as a positive start', 'Enkla aktiviteter som ger kontinuerlig bollkontakt, kreativitet och mod att utmana.', 'Varför dribbling är central tidigt och hur tränaren kan uppmuntra försök.', 'Belöna ett modigt dribblingsförsök lika tydligt som ett mål.', 'Teknik med boll', '5–8 år', true, true, false, '3 mot 3; 5 mot 5', true, true, false, 'Grund', 'Artikel + film + övningar', 'Engelska', 'FIFA Training Centre', 'Internationellt förbund', 8, 'Direkt användbar', 'Officiellt utbildningsmaterial', 'https://www.fifatrainingcentre.com/en/practice/grassroots/grassroots-and-youth-football-essentials/grassroots-coaching-essentials/jene-3-dribbling-as-a-positive-start.php', '2026-08-30', true, true, 12, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB013', 'utveckla-skott', 'Utveckla skottfärdigheter', 'Ages 4-8: Developing shooting skills', 'Skottträning med fokus på enkel teknik, självförtroende, repetition, tävling och smålagsspel.', 'Hur precision kan prioriteras före kraft och svårigheten ökas stegvis.', 'Ställ upp flera små mål så att varje barn får många avslut utan kö.', 'Teknik med boll', '5–8 år', true, true, false, '3 mot 3; 5 mot 5', true, true, false, 'Grund', 'Artikel + film + övningar', 'Engelska', 'FIFA Training Centre', 'Internationellt förbund', 8, 'Direkt användbar', 'Officiellt utbildningsmaterial', 'https://www.fifatrainingcentre.com/en/practice/grassroots/grassroots-and-youth-football-essentials/grassroots-coaching-essentials/developing-shooting-skills.php', '2026-08-30', true, false, 13, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB014', 'olika-satt-att-gora-mal', 'Skapa flera sätt att göra mål', 'Ages 4-8: Creating different ways to score', 'Övningar som låter barn experimentera med olika avslut och upptäcka lösningar i stället för att kopiera en enda teknik.', 'Hur målregler kan styra variation, val och kreativitet.', 'Spela med två olika måltyper och låt barnen själva upptäcka när respektive mål passar.', 'Teknik med boll', '5–8 år', true, true, false, '3 mot 3; 5 mot 5', true, true, false, 'Grund', 'Artikel + film + övningar', 'Engelska', 'FIFA Training Centre', 'Internationellt förbund', 8, 'Direkt användbar', 'Officiellt utbildningsmaterial', 'https://www.fifatrainingcentre.com/en/practice/grassroots/grassroots-and-youth-football-essentials/grassroots-coaching-essentials/creating-different-ways-to-score.php', '2026-08-30', true, false, 14, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB015', 'bollfardigheter-5-11', 'Hjälp barn att utveckla bollfärdigheter', 'How to help 5-11s develop their skills on the ball', 'Om att ge barn tid på bollen, uppmuntra hotande och kreativa val samt acceptera misstag under lärandet.', 'Hur tränarens regler och språk kan öka spelarnas ägarskap över bollen.', 'Inför fem minuter där tränaren inte får ropa instruktioner under spelet.', 'Teknik med boll', '5–10 år', true, true, true, 'Alla smålagsspel', true, true, true, 'Grund', 'Artikel', 'Engelska', 'England Football Learning', 'Nationellt förbund', 2, 'Snabb inspiration', 'Officiellt utbildningsmaterial', 'https://learn.englandfootball.com/articles-and-resources/coaching/resources/2023/How-to-help-5-11s-develop-their-skills-on-the-ball', '2026-08-30', true, false, 15, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB016', 'passning-mottagning-sex-veckor', 'Sex veckor: passning och mottagning', 'Session programme: passing and receiving to score', 'Ett färdigt sexveckorsprogram för passningsteknik, kombinationer, mottagning och att skapa målchanser.', 'Hur ett tema kan utvecklas över flera veckor med tydlig progression.', 'Välj första veckans pass som grund och anpassa bara yta och antal spelare.', 'Teknik med boll', '7–10 år', true, true, true, '5 mot 5; 7 mot 7', false, true, true, 'Fortsättning', 'Sexveckorsprogram + övningar', 'Engelska', 'England Football Learning', 'Nationellt förbund', 15, 'Färdig träningsserie', 'Officiellt utbildningsmaterial', 'https://learn.englandfootball.com/sessions/resources/2025/Session-programme-passing-and-receiving-to-score', '2026-08-30', true, true, 16, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB017', 'driva-och-vanda-sex-veckor', 'Sex veckor: driva boll och vända', 'Session programme: Moving with the ball and turning to attack', 'En färdig serie om bolltransport, riktningsförändringar, finter, scanning och att spela framåt.', 'Hur tekniska detaljer kan tränas i lekar, parövningar och spel.', 'Låt barnen växla mellan små touch nära motståndare och större touch på fri yta.', 'Teknik med boll', '7–10 år', true, true, true, '5 mot 5; 7 mot 7', false, true, true, 'Fortsättning', 'Sexveckorsprogram + övningar', 'Engelska', 'England Football Learning', 'Nationellt förbund', 15, 'Färdig träningsserie', 'Officiellt utbildningsmaterial', 'https://learn.englandfootball.com/sessions/resources/2025/Session-programme-moving-with-the-ball-and-turning-to-attack', '2026-08-30', true, false, 17, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB018', 'forsta-och-anvanda-ytor', 'Bygg förståelse för ytor', 'Ages 4-8: Building spatial awareness in young players', 'En första taktisk introduktion där barn lär sig se lediga ytor, undvika trängsel och hitta plats med och utan boll.', 'Hur ytförståelse kan läras genom spel och frågor i stället för fasta positioner.', 'Pausa en gång och fråga: Var finns den största tomma ytan just nu?', 'Spelförståelse och taktik', '5–8 år', true, true, false, '3 mot 3; 5 mot 5', true, true, false, 'Grund', 'Artikel + film + övningar', 'Engelska', 'FIFA Training Centre', 'Internationellt förbund', 8, 'Direkt användbar', 'Officiellt utbildningsmaterial', 'https://www.fifatrainingcentre.com/en/practice/grassroots/grassroots-and-youth-football-essentials/grassroots-coaching-essentials/building-spatial-awareness-in-young-players.php', '2026-08-30', true, true, 18, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB019', 'numerisk-progression', 'Lär genom numeriska progressionsspel', 'Ages 8-12: Learning through numeric progression games', 'Spelformer som stegvis ändrar antalet spelare och därmed tränar beslut i över-, under- och liktalighet.', 'Hur samma tema kan göras lättare eller svårare genom spelarantalet.', 'Börja 1 mot 1, lägg sedan till en medspelare och fråga vad som förändrades.', 'Spelförståelse och taktik', '8–10 år', false, true, true, '3 mot 3; 5 mot 5', true, true, false, 'Fortsättning', 'Artikel + film + övningar', 'Engelska', 'FIFA Training Centre', 'Internationellt förbund', 9, 'Direkt användbar', 'Officiellt utbildningsmaterial', 'https://www.fifatrainingcentre.com/en/practice/grassroots/grassroots-and-youth-football-essentials/grassroots-coaching-essentials/learning-through-numeric-progression-games.php', '2026-08-30', true, false, 19, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB020', 'tvamals-spel', 'Träningsdesign med två mål', 'Practice design in football: two-goal games', 'Visar hur ett vanligt spel mot två mål kan förändras för att skapa olika beslut och fotbollsaktioner.', 'Hur planstorlek, mål och regler påverkar vad barnen övar.', 'Ändra bara en sak i spelet – exempelvis planens bredd – och fråga spelarna vad som blev annorlunda.', 'Spelförståelse och taktik', '5–10 år', true, true, true, '3 mot 3; 5 mot 5; 7 mot 7', true, true, true, 'Fortsättning', 'Artikel + film', 'Engelska', 'England Football Learning', 'Nationellt förbund', 4, 'Snabb inspiration', 'Officiellt utbildningsmaterial', 'https://learn.englandfootball.com/articles-and-resources/coaching/resources/2022/practice-design-in-football-two-goal-games', '2026-08-30', true, false, 20, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB021', 'press-och-tackning-sex-veckor', 'Sex veckor: press och täckning', 'Session programme: pressing and covering to stop goals', 'En progressiv träningsserie från 1 mot 1 till smålagsspel om närmaste press, täckande understöd och återerövring.', 'Hur grundläggande försvarssamarbete kan tränas utan långa taktiska föreläsningar.', 'Spela 2 mot 2 och be laget utan boll alltid ha en som pressar och en som hjälper bakom.', 'Spelförståelse och taktik', '8–10 år', false, true, true, '5 mot 5; 7 mot 7', false, true, true, 'Fortsättning', 'Sexveckorsprogram + övningar', 'Engelska', 'England Football Learning', 'Nationellt förbund', 15, 'Färdig träningsserie', 'Officiellt utbildningsmaterial', 'https://learn.englandfootball.com/sessions/resources/2025/Session-programme-pressing-and-covering-to-stop-goals', '2026-08-30', true, false, 21, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB022', 'nationella-spelformer', 'Fotbollens nationella spelformer', 'Fotbollens nationella spelformer', 'SvFF:s samlingssida för 3 mot 3, 5 mot 5 och 7 mot 7, med mål, förutsättningar och åldersanpassning.', 'Vilken spelform som hör till åldern och varför små format ger fler aktioner.', 'Kontrollera att träningsspelets plan och spelarantal motsvarar det ni vill att barnen ska få göra ofta.', 'Match och spelformer', '5–10 år', true, true, true, '3 mot 3; 5 mot 5; 7 mot 7', true, true, true, 'Grund', 'Guide och regelöversikt', 'Svenska', 'Svenska Fotbollförbundet', 'Nationellt förbund', 10, 'Referensmaterial', 'Officiella riktlinjer', 'https://aktiva.svenskfotboll.se/tranare/spelformer/', '2026-08-30', true, true, 22, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
('KB023', 'fragor-svar-spelformer', 'Frågor och svar om spelformerna', 'Varför finns fotbollens nationella spelformer?', 'Förklarar tanken bakom regler och format, bland annat hur de ska stimulera utveckling, motivation och jämna matcher.', 'Varför regler som retreatlinje och extra spelare används i barnfotboll.', 'Förklara retreatlinjens syfte för båda lagens ledare före nästa 5 mot 5-match.', 'Match och spelformer', '5–10 år', true, true, true, '3 mot 3; 5 mot 5; 7 mot 7', true, true, true, 'Grund', 'Frågor och svar', 'Svenska', 'Svenska Fotbollförbundet', 'Nationellt förbund', 8, 'Referensmaterial', 'Officiella riktlinjer', 'https://aktiva.svenskfotboll.se/tranare/spelformer/fragor-svar/', '2026-08-30', true, false, 23, 'Egen svensk sammanfattning. Återpublicera inte originaltext eller originalbilder; länka till källan.'),
